using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

namespace Oathx.Core
{
    /// <summary>
    /// Controls the Loading and Update panels in Assets/Data/Widgets/Launch/Launch.
    /// Available before the game plugin and UISystem are initialized.
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(RectTransform))]
    public class XLauncher : UIBehaviour
    {
        /// <summary>
        /// Root of the regular loading panel.
        /// </summary>
        [SerializeField]
        private GameObject loading;

        /// <summary>
        /// Root of the resource download panel.
        /// </summary>
        [SerializeField]
        private GameObject update;

        /// <summary>
        /// Status message displayed during regular loading.
        /// </summary>
        [SerializeField]
        private Text loadingText;

        /// <summary>
        /// Progress percentage displayed in the loading panel.
        /// </summary>
        [SerializeField]
        private Text loadingPercent;

        /// <summary>
        /// Additional tip displayed in the loading panel.
        /// </summary>
        [SerializeField]
        private Text tip;

        /// <summary>
        /// Status message displayed during resource downloads.
        /// </summary>
        [SerializeField]
        private Text downloadText;

        /// <summary>
        /// Progress percentage displayed in the download panel.
        /// </summary>
        [SerializeField]
        private Text downloadPercent;

        /// <summary>
        /// RawImage rectangle stretched to represent download progress.
        /// </summary>
        [SerializeField]
        private RectTransform fill;

        /// <summary>
        /// Download progress indicator positioned along the handle area.
        /// </summary>
        [SerializeField]
        private RectTransform handle;

        /// <summary>
        /// Whether progress updates target the download panel.
        /// </summary>
        private bool downloading;

        /// <summary>
        /// Show the view without resetting its current progress.
        /// </summary>
        public void Show()
        {
            gameObject.SetActive(true);
        }

        /// <summary>
        /// Hide the view while preserving its current state.
        /// </summary>
        public void Hide()
        {
            gameObject.SetActive(false);
        }

        /// <summary>
        /// Keep the launch background visible without loading or download overlays.
        /// </summary>
        public void ShowBackground()
        {
            loading.SetActive(false);
            update.SetActive(false);

            Show();
        }

        /// <summary>
        /// Display the regular loading panel.
        /// </summary>
        /// <param name="message">Initial status message; progress is reset to zero.</param>
        public void ShowLoading(string message = "Loading...")
        {
            downloading = false;

            loading.SetActive(true);
            update.SetActive(false);

            UpdateProgress(0f, message);
        }

        /// <summary>
        /// Display the resource download panel.
        /// </summary>
        /// <param name="message">Initial download message; progress is reset to zero.</param>
        public void ShowUpdate(string message = "Downloading resources...")
        {
            downloading = true;
            
            loading.SetActive(false);
            update.SetActive(true);

            UpdateProgress(0f, message);
        }

        /// <summary>
        /// Set the additional loading tip.
        /// </summary>
        /// <param name="text">Tip text to display.</param>
        public void SetTip(string text)
        {
            tip.text = text;
        }

        /// <summary>
        /// Update the active panel. The prefab uses a RawImage fill, not an Image or Slider.
        /// </summary>
        /// <param name="progress">Normalized progress, clamped to zero through one; NaN becomes zero.</param>
        /// <param name="text">Status message for the active panel.</param>
        /// <returns>True when the active panel has been updated.</returns>
        public bool UpdateProgress(float progress, string text)
        {
            progress = float.IsNaN(progress) ? 0f : Mathf.Clamp01(progress);
            int percent = Mathf.RoundToInt(progress * 100f);
            if (!downloading)
            {
                // Current templates combine the message and percentage in DownloadTips.
                // Retain the separate label when an older prefab still supplies one.
                loadingText.text = loadingPercent ? text : $"{text} ({percent}%)";
                if (loadingPercent) loadingPercent.text = $"({percent}%)";
                return true;
            }

            downloadText.text = downloadPercent ? text : $"{text} {percent}%";
            if (downloadPercent) downloadPercent.text = $"{percent}%";
            // Preserve the authored vertical offsets while stretching horizontally.
            fill.anchorMin = new Vector2(0f, fill.anchorMin.y);
            fill.anchorMax = new Vector2(progress, fill.anchorMax.y);
            fill.offsetMin = new Vector2(0f, fill.offsetMin.y);
            fill.offsetMax = new Vector2(0f, fill.offsetMax.y);
            handle.anchorMin = new Vector2(progress, handle.anchorMin.y);
            handle.anchorMax = new Vector2(progress, handle.anchorMax.y);
            handle.anchoredPosition = new Vector2(0f, handle.anchoredPosition.y);

            return true;
        }
    }
}

using Oathx.Core;
using Oathx.Entity;
using Oathx.Widget;

/// <summary>
/// Manages the SV login page lifecycle.
/// </summary>
public class LoginSystem : RuntimeSystem
{
    /// <summary>
    /// Load and open the SV login page through UISystem.
    /// </summary>
    /// <returns>True after starting the page open request; false if the system is inactive.</returns>
    public override bool OnActive()
    {
        if (!IsActive())
            return false;

        UISystem.GetSingleton().OpenWidget<UILogin>((widget) => {
            if (widget)
            {
                widget.vm.EnterClick = (sender) => EnterGame(widget.vm);
                widget.vm.CanEnter = true;

                XApp.GetSingleton().ShowLaunchBackground();
            }
        });

        return true;
    }

    /// <summary>
    /// Publish local login success when the player enters the game.
    /// </summary>
    /// <param name="vm">View model controlling the enter button.</param>
    /// <returns>True when the local login success event has been queued.</returns>
    private bool EnterGame(VMLogin vm)
    {
        if (!IsActive() || !vm || !vm.CanEnter)
            return false;

        if (!XEntityManager.GetSingleton().TryGetEntity(nameof(MasterEntity), out var entity)
            || !(entity is MasterEntity master))
            return false;

        return XPluginUtility.PostEvent(new LoginSucceed() {
            pid = master.GetAttr(MasterPropertyDef.PID)
        });
    }

    /// <summary>
    /// Release subscriptions and close the SV login page when deactivated.
    /// </summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        UISystem.GetSingleton().CloseWidget<UILogin>(immediate: true);
    }
}

using Oathx.Entity;
using Oathx.HttpProtocol;
using UnityEngine;

/// <summary>
/// 
/// </summary>
[Initialize]
public partial class LoginEntity : XEntity
{
    /// <summary>
    /// constructor
    /// </summary>
    public int pid
    { get; set; }

    /// <summary>
    /// login time
    /// </summary>
    public long loginAt
    { get; set; }

    /// <summary>
    /// create time
    /// </summary>
    public long tmcreate
    { get; set; }

    /// <summary>
    /// query login entity
    /// </summary>
    /// <param name="response"></param>
    /// <returns></returns>
    public bool Refresh(LoginResponse response)
    {
        pid = response.pid; loginAt = response.loginAt; tmcreate = response.tmcreate;
        return true;
    }
}

using Oathx.Widget;

/// <summary>
/// SV login view with serialized Widget Metadata bindings.
/// </summary>
[Config("Assets/Data/Widgets/SVLogin/SVLogin.prefab", WidgetLayer.center, cacheWidget: false)]
public class UILogin : UIWidget<VMLogin>
{
    /// <summary>
    /// Refresh the account display from the existing login entity.
    /// </summary>
    /// <param name="entity">Current login data.</param>
    /// <returns>True when the view model was refreshed.</returns>
    public bool Invalidate(LoginEntity entity)
    {
        if (!entity || !vm)
            return false;

        vm.Username = entity.pid > 0 ? entity.pid.ToString() : string.Empty;
        return true;
    }
}

